JS = """
function filterFindings(sev) {
  const items = document.querySelectorAll('.finding-item');
  const btns = document.querySelectorAll('.filter-btn');
  btns.forEach(b => b.classList.toggle('active', b.dataset.sev === sev || (sev === 'all' && b.dataset.sev === 'all')));
  items.forEach(item => {
    if (sev === 'all') { item.style.display = 'flex'; }
    else if (sev === 'open') { item.style.display = item.dataset.status === 'open' ? 'flex' : 'none'; }
    else if (sev === 'fixed') { item.style.display = item.dataset.status === 'fixed' ? 'flex' : 'none'; }
    else { item.style.display = item.dataset.sev === sev ? 'flex' : 'none'; }
  });
}
document.addEventListener('DOMContentLoaded', () => filterFindings('all'));
"""


def _html_phase_bar(s: dict) -> str:
    stages = [p for p in s["pipeline"].get("stages", []) if p["name"] != "COMPLETE"]
    nodes = []
    for stage in stages:
        status = stage["status"]
        css = {"complete": "done", "active": "active"}.get(status, "pending")
        label = {"complete": "✓ Complete", "active": "● Active"}.get(status, "○ Pending")
        dur = f'<div class="phase-duration">⏱ {stage["duration"]}</div>' if status == "complete" and stage["duration"] != "—" else ""
        icon = STAGE_ICON.get(stage["name"], "")
        nodes.append(f'''
        <div class="phase-node">
          <div class="phase-box {css}">
            <div class="phase-name">{icon} {stage["name"]}</div>
            <div class="phase-status">{label}</div>
            {dur}
          </div>
        </div>''')
    return f'<div class="timeline">{"".join(nodes)}</div>'


def _html_summary_cards(s: dict) -> str:
    pipe = s["pipeline"]
    findings = s["findings"]
    total_receipts = pipe.get("stories_with_receipts", 0)
    stages_done = sum(1 for p in pipe.get("stages", []) if p["status"] == "complete")
    total_stages = len(pipe.get("stages", []))
    crit = findings["summary"].get("critical", 0)
    high = findings["summary"].get("high", 0)
    fixed_total = sum(findings["fixed"].values())
    ctx = [p for p in s.get("context_packages", []) if p["status"] == "generated"]

    cards = [
        ("Stories", str(total_receipts), "with receipts"),
        ("Stages", f"{stages_done}/{total_stages}", "lifecycle stages"),
        ("Findings", str(sum(findings["summary"].values())),
         f"{crit}C · {high}H · {fixed_total} fixed"),
    ]
    if ctx:
        cards.append(("Context Pkgs", str(len(ctx)), "brownfield packages"))

    html = ""
    for label, value, sub in cards:
        html += f'''
        <div class="card">
          <div class="card-label">{label}</div>
          <div class="card-value">{value}</div>
          <div class="card-sub">{sub}</div>
        </div>'''
    return html


def _html_agent_cards(s: dict) -> str:
    all_agents = []
    for phase in s["pipeline"]["phases"]:
        for agent in phase["agents"]:
            all_agents.append((phase["name"], agent))

    if not all_agents:
        return '<div class="empty">No agent receipts yet.</div>'

    cards = []
    for phase_name, agent in all_agents:
        name = escape(agent["agent"])
        if agent.get("mode"):
            name += f' [{escape(agent["mode"])}]'
        task = escape(agent["task_id"])

        metrics_html = ""
        for k, v in agent.get("metrics", {}).items():
            if v and not isinstance(v, str):
                metrics_html += f'<div class="metric"><strong>{escape(str(v))}</strong> {escape(k.replace("_", " "))}</div>'

        eff = agent["effort"]
        effort_html = ""
        if any(eff.values()):
            effort_html = '<div class="effort">'
            if eff["files_read"]:
                effort_html += f'<span class="effort-item">📖 {eff["files_read"]} read</span>'
            if eff["files_written"]:
                effort_html += f'<span class="effort-item">✏️ {eff["files_written"]} written</span>'
            if eff["tool_calls"]:
                effort_html += f'<span class="effort-item">🔧 {eff["tool_calls"]} calls</span>'
            effort_html += '</div>'

        ver = agent.get("verification", "")
        ver_html = ""
        if ver and isinstance(ver, str):
            ver_html = f'<div class="verification">{escape(ver[:200])}</div>'

        cards.append(f'''
        <div class="agent-card complete">
          <div class="agent-header">
            <span class="agent-name">{task} — {name}</span>
            <span class="agent-phase">{escape(phase_name)}</span>
          </div>
          <div class="metrics">{metrics_html}</div>
          {effort_html}
          {ver_html}
        </div>''')

    return f'<div class="agents">{"".join(cards)}</div>'


def _html_findings(s: dict) -> str:
    items = s["findings"]["items"]
    if not items:
        return '<div class="empty">No findings detected.</div>'

    counts = {}
    open_count = fixed_count = 0
    for f in items:
        sev = f["severity"]
        counts[sev] = counts.get(sev, 0) + 1
        if f["status"] == "fixed":
            fixed_count += 1
        else:
            open_count += 1

    btns = '<button class="filter-btn active" data-sev="all" onclick="filterFindings(\'all\')">All</button>'
    if open_count:
        btns += f'<button class="filter-btn" data-sev="open" onclick="filterFindings(\'open\')">Open ({open_count})</button>'
    if fixed_count:
        btns += f'<button class="filter-btn" data-sev="fixed" onclick="filterFindings(\'fixed\')">Fixed ({fixed_count})</button>'
    for sev in ["critical", "high", "medium", "low"]:
        if sev in counts:
            btns += f'<button class="filter-btn" data-sev="{sev}" onclick="filterFindings(\'{sev}\')">{sev.capitalize()} ({counts[sev]})</button>'

    html_items = []
    for f in items:
        sev = f["severity"]
        color = SEV_COLOR.get(sev, "#6b7280")
        status = f["status"]
        status_css = "fixed" if status == "fixed" else ""
        status_badge = f'<span class="status-fixed">✓ Fixed</span>' if status == "fixed" else f'<span class="status-open">Open</span>'
        ref = f'<span>{escape(f["file_ref"])}</span>' if f.get("file_ref") else ""
        fid = f'<span>{escape(f.get("id", ""))}</span>' if f.get("id") else ""
        fixed_by = f'<span>Fixed by {escape(f["fixed_by"])}</span>' if f.get("fixed_by") else ""

        html_items.append(f'''
        <div class="finding-item {status_css}" data-sev="{sev}" data-status="{status}">
          <div class="sev-dot" style="background:{color}"></div>
          <div>
            <div class="finding-title">{escape(f["title"])}</div>
            <div class="finding-meta">
              <span style="color:{color};background:transparent;font-weight:600">{sev.capitalize()}</span>
              {status_badge}{fid}{ref}{fixed_by}
            </div>
          </div>
        </div>''')

    return f'<div class="findings-filter">{btns}</div>' + "".join(html_items)


def _html_dod_summary(s: dict) -> str:
    dod = s.get("dod_summary")
    if not dod:
        return '<div class="empty">No DoD data available yet.</div>'

    inception = "✓ Approved" if dod.get("inception_gate") == "approved" else "○ Pending"
    inception_css = "gate-approved" if dod.get("inception_gate") == "approved" else "gate-pending"
    passed = dod.get("stories_passed", 0)
    evaluated = dod.get("stories_evaluated", 0)
    rate = dod.get("pass_rate", 0)

    html = [f'''
        <div class="gate-item">
          <div class="gate-header">
            <span class="gate-title">⬥ Inception Gate</span>
            <span class="{inception_css}">{inception}</span>
          </div>
        </div>
        <div class="gate-item">
          <div class="gate-header">
            <span class="gate-title">⬥ Story DoD</span>
            <span class="gate-detail">{passed}/{evaluated} passed ({rate:.0%})</span>
          </div>
        </div>''']
    return "".join(html)


def _html_sprint_progress(s: dict) -> str:
    sprint = s.get("sprint")
    if not sprint:
        return ""

    STATUS_STYLE = {
        "complete": ("var(--green)", "✓ Complete"),
        "demo_ready": ("var(--yellow)", "🎯 Demo Ready"),
        "build": ("var(--accent2)", "▸ Building"),
        "verify": ("var(--accent2)", "▸ Verifying"),
        "refinement": ("var(--orange)", "↻ Refinement"),
        "active": ("var(--accent2)", "▸ Active"),
        "planned": ("var(--muted)", "○ Planned"),
    }

    rows = []
    for sp in sprint.get("sprints", []):
        color, label = STATUS_STYLE.get(sp["status"], ("var(--muted)", sp["status"].capitalize()))
        rows.append(f'''
        <tr>
          <td style="font-weight:600">Sprint {sp['number']}</td>
          <td>{escape(sp['type'])}</td>
          <td>{escape(sp['stories'])}</td>
          <td>{escape(sp['findings'])}</td>
          <td style="color:{color}">{label}</td>
        </tr>''')

    completed = sprint["sprints_completed"]
    total = sprint["total_sprints"]
    current = sprint["current_sprint"]
    phase = sprint["sprint_phase"].replace("_", " ") if sprint["sprint_phase"] else "active"

    return f'''
    <table class="data-table">
      <thead>
        <tr><th>Sprint</th><th>Type</th><th>Stories</th><th>Findings</th><th>Status</th></tr>
      </thead>
      <tbody>{"".join(rows)}</tbody>
    </table>
    <div style="margin-top:10px;font-size:13px;color:var(--muted)">
      <strong style="color:var(--text)">{completed}/{total}</strong> sprints complete
      — Sprint {current} {escape(phase)}
    </div>'''


def _html_sprint_detail(s: dict) -> str:
    detail = s.get("sprint_detail")
    if not detail:
        return ""

    header = detail["header"]
    board = detail["story_board"]
    dod = detail["dod_checklist"]
    summary = detail["summary"]

    SEV_DOT = {"critical": "#ef4444", "high": "#f97316", "medium": "#eab308", "low": "#6b7280"}
    STATUS_CSS = {
        "done": ("var(--green)", "✓ Done"),
        "review": ("var(--yellow)", "⚠ Review"),
        "in_progress": ("var(--accent2)", "↻ In Progress"),
        "blocked": ("var(--red)", "✗ Blocked"),
        "not_started": ("var(--muted)", "○ Not Started"),
    }

    # ── Sprint header card
    meta_parts = []
    if header["dates"]:
        meta_parts.append(f'<span class="badge badge-type">{escape(header["dates"])}</span>')
    if header["capacity"]:
        meta_parts.append(f'<span class="badge badge-type">{escape(header["capacity"])}</span>')
    if header["phase"]:
        phase_display = header["phase"].replace("_", " ").capitalize()
        meta_parts.append(f'<span class="badge badge-phase">{escape(phase_display)}</span>')

    header_html = f'''
    <div class="card" style="margin-bottom:16px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
        <div style="font-size:16px;font-weight:700">Sprint {header["number"]}</div>
        <div style="display:flex;gap:6px">{"".join(meta_parts)}</div>
      </div>
      <div style="font-size:13px;color:var(--muted)">{escape(header["goal"])}</div>
    </div>'''

    # ── Story board table
    story_rows = ""
    for st in board:
        color, label = STATUS_CSS.get(st["status"], ("var(--muted)", st["status"]))
        if st["acs_total"]:
            acs_str = f'{st["acs_met"]}/{st["acs_total"]}'
        elif not st.get("has_brd", True):
            acs_str = "N/A"
        else:
            acs_str = "—"
        tests_str = str(st["test_count"]) if st["test_count"] else "—"
        findings_html = "—"
        if st["findings_count"] > 0:
            highest_color = "#ef4444" if any(f["severity"] == "critical" for f in st["findings"]) else \
                            "#f97316" if any(f["severity"] == "high" for f in st["findings"]) else "#eab308"
            findings_html = f'<span style="color:{highest_color};font-weight:600">{st["findings_count"]}</span>'

        story_rows += f'''
        <tr>
          <td style="font-weight:600">{escape(st["id"])}</td>
          <td>{escape(st["title"])}</td>
          <td>{escape(st["size"] or "—")}</td>
          <td>{acs_str}</td>
          <td>{tests_str}</td>
          <td>{findings_html}</td>
          <td style="color:{color}">{label}</td>
        </tr>'''

    board_html = f'''
    <div style="margin-bottom:8px;font-size:13px;font-weight:600;color:var(--text)">
      Story Board — {summary["stories_done"] + summary["stories_review"]}/{summary["stories_total"]} complete
    </div>
    <table class="data-table">
      <thead>
        <tr><th>ID</th><th>Title</th><th>Size</th><th>ACs</th><th>Tests</th><th>Findings</th><th>Status</th></tr>
      </thead>
      <tbody>{story_rows}</tbody>
    </table>
    <div style="margin-top:8px;font-size:12px;color:var(--muted)">
      {summary["stories_done"]} Done · {summary["stories_review"]} Review ·
      {summary["stories_in_progress"]} In Progress · {summary["stories_blocked"]} Blocked
      {f' · Must: {summary["must_completion"]}%' if summary.get("must_completion") else ""}
    </div>'''

    # ── AC drill-down (collapsible, only for review stories)
    ac_html = ""
    review_stories = [st for st in board if st["status"] == "review" and st["acs"]]
    if review_stories:
        ac_sections = ""
        for st in review_stories:
            ac_rows = ""
            for ac in st["acs"]:
                if ac["status"] == "met":
                    ac_badge = '<span style="color:var(--green);font-weight:600">✓ Met</span>'
                elif ac["status"] == "finding":
                    ref = f' <span style="font-size:11px;color:var(--red)">({escape(ac["finding_ref"])})</span>' if ac["finding_ref"] else ""
                    ac_badge = f'<span style="color:var(--yellow);font-weight:600">⚠ Finding</span>{ref}'
                else:
                    ac_badge = '<span style="color:var(--muted)">○ Unknown</span>'
                ac_rows += f'<tr><td style="font-weight:600;width:60px">{escape(ac["id"])}</td><td>{escape(ac["text"])}</td><td>{ac_badge}</td></tr>'

            # Inline finding details
            finding_details = ""
            if st["findings"]:
                for f in st["findings"]:
                    sev_color = SEV_DOT.get(f["severity"], "#6b7280")
                    finding_details += f'''
                    <div style="display:flex;gap:8px;align-items:center;padding:4px 0">
                      <span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:{sev_color};flex-shrink:0"></span>
                      <span style="font-size:12px"><strong>{escape(f.get("id", ""))}</strong> {escape(f["title"])}</span>
                    </div>'''

            ac_sections += f'''
            <details style="margin-bottom:12px">
              <summary style="cursor:pointer;font-weight:600;font-size:13px;margin-bottom:6px">
                {escape(st["id"])} — {escape(st["title"])}  <span style="color:var(--yellow)">⚠ Review</span>
              </summary>
              <table class="data-table" style="margin-bottom:8px">
                <thead><tr><th>AC</th><th>Description</th><th>Status</th></tr></thead>
                <tbody>{ac_rows}</tbody>
              </table>
              {finding_details}
            </details>'''

        ac_html = f'''
    <div style="margin-top:20px;margin-bottom:8px;font-size:13px;font-weight:600;color:var(--text)">
      AC Drill-Down — Stories with Findings
    </div>
    {ac_sections}'''

    # ── DoD checklist
    dod_html = ""
    if dod:
        DOD_STYLE = {
            "met": ("var(--green)", "✓"),
            "blocked": ("var(--yellow)", "⚠"),
            "pending": ("var(--muted)", "○"),
        }
        dod_items = ""
        for item in dod:
            color, icon = DOD_STYLE.get(item["status"], ("var(--muted)", "○"))
            dod_items += f'''
            <div style="display:flex;gap:10px;align-items:center;padding:6px 0;border-bottom:1px solid var(--border)">
              <span style="color:{color};font-weight:700;font-size:14px;width:20px;text-align:center">{icon}</span>
              <span style="font-size:13px">{escape(item["text"])}</span>
            </div>'''

        dod_met = summary.get("dod_met", 0)
        dod_total = summary.get("dod_total", 0)
        dod_blocked = summary.get("dod_blocked", 0)

        dod_html = f'''
    <div style="margin-top:20px;margin-bottom:8px;font-size:13px;font-weight:600;color:var(--text)">
      Definition of Done
    </div>
    <div class="card" style="padding:12px 16px">
      {dod_items}
      <div style="margin-top:10px;font-size:12px;color:var(--muted)">
        <strong style="color:var(--text)">{dod_met}/{dod_total}</strong> met ·
        {dod_blocked} blocked
      </div>
    </div>'''

    return header_html + board_html + ac_html + dod_html


def render_html(summary: dict) -> str:
    proj = summary["project"]
    pipe = summary["pipeline"]
    findings = summary["findings"]
    total_agents = sum(len(p["agents"]) for p in pipe["phases"])
    crit = findings["summary"].get("critical", 0)
    high = findings["summary"].get("high", 0)
    fixed_total = sum(findings["fixed"].values())
    findings_label = f"{crit}C · {high}H · {fixed_total} fixed" if sum(findings["summary"].values()) else "none"

    sprint = summary.get("sprint")
    sprint_badge = ""
    if sprint:
        sprint_badge = (
            f'<span class="badge badge-mode">Sprint {sprint["current_sprint"]}'
            f'/{sprint["total_sprints"]} ({sprint["sprint_phase"] or "active"})</span>'
        )

    sprint_section = ""
    sprint_html = _html_sprint_progress(summary)
    if sprint_html:
        sprint_section = f'''
  <div class="section">
    <div class="section-title">Sprint Progress</div>
    {sprint_html}
  </div>'''

    sprint_detail_section = ""
    sprint_detail_html = _html_sprint_detail(summary)
    if sprint_detail_html:
        sprint_detail_section = f'''
  <div class="section">
    <div class="section-title">Sprint Detail</div>
    {sprint_detail_html}
  </div>'''

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>synaptory · {escape(proj['name'])}</title>
<style>{CSS}</style>
</head>
<body>
<div class="container">

  <div class="header">
    <div>
      <h1>◆ synaptory · <span>{escape(proj['name'])}</span></h1>
      <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">
        <span class="badge badge-mode">⚙ {escape(proj['engagement'].capitalize())}</span>
        <span class="badge badge-phase">▸ {escape(pipe.get('lifecycle_state', 'UNKNOWN'))}</span>
        {sprint_badge}
        <span class="badge badge-type">⏱ {escape(pipe['total_elapsed'])}</span>
        <span class="badge badge-type">Findings: {findings_label}</span>
      </div>
    </div>
    <div style="text-align:right;color:var(--muted);font-size:12px">
      Generated<br>{summary['generated_at_display']}
    </div>
  </div>

  <div class="summary">
    {_html_summary_cards(summary)}
  </div>

  <div class="section">
    <div class="section-title">Pipeline Phases</div>
    {_html_phase_bar(summary)}
  </div>

  {sprint_section}

  {sprint_detail_section}

  <div class="section">
    <div class="section-title">Agent Completions ({total_agents})</div>
    {_html_agent_cards(summary)}
  </div>

  <div class="section">
    <div class="section-title">Findings ({len(findings['items'])})</div>
    {_html_findings(summary)}
  </div>

  <div class="section">
    <div class="section-title">Definition of Done</div>
    {_html_dod_summary(summary)}
  </div>

  <div class="footer">
    synaptory pipeline report · {escape(proj['name'])} · {summary['generated_at_display']}
  </div>

</div>
<script>{JS}</script>
</body>
</html>"""

